(async () => {
    const m = window.__mymechanics;
    await m.actions.ensureKernel();
    await m.actions.closeProject({ force: true });
    await m.actions.newDocument('part');
    const F = await import('/src/cad/features.js'); const S = await import('/src/cad/sketch.js');
    const part = m.active(); part.name = 'Twin';
    const top = { kind: 'std', name: 'top' };
    const a = F.createFeature(part, 'sketch', { plane: top, ...S.createSketchGeometry() }); S.addRectangle(a, 0, 0, 20, 20);
    const b = F.createFeature(part, 'sketch', { plane: top, ...S.createSketchGeometry() }); S.addRectangle(b, 40, 0, 70, 20);
    m.actions.change('op.addFeature', () => { part.features.push(a, F.createFeature(part, 'extrude', { sketch: a.id, depth: 10 }), b, F.createFeature(part, 'extrude', { sketch: b.id, depth: 10, merge: false })); });
    await new Promise((r) => setTimeout(r, 300));
    return String(m.project.parts.length);
  })()

(async () => {
    const m = window.__mymechanics; const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
    await m.run('saveBodies'); await sleep(400);
    const parts = m.project.parts.filter((p) => p.name.startsWith('Twin-'));
    const R = m.actions.buildPart(parts[1]).body;
    const vol = (await import('/src/cad/kernel.js')).rep().measureVolume(R);
    const asm = m.project.assemblies.at(-1);
    // Open the second one and edit its Insert Part feature: the body drop-down shows "Body 2".
    await m.actions.switchDocument({ kind: 'part', id: parts[1].id });
    m.actions.cancelEditing?.({ quiet: true });
    await m.actions.editFeature(parts[1].features[0].id); await sleep(300);
    const sel = document.querySelector('[data-pm-select="body"]');
    const shown = sel ? sel.options[sel.selectedIndex].textContent : 'none';
    m.actions.cancelEditing({ quiet: true });
    return `${parts.length} ${Math.round(vol)} ${asm.components.length} ${shown}`;
  })()

(async () => {
    const m = window.__mymechanics; const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
    const twin = m.project.parts.find((p) => p.name === 'Twin');
    await m.actions.switchDocument({ kind: 'part', id: twin.id });
    m.actions.cancelEditing?.({ quiet: true });
    await m.run('intersect'); await sleep(800);
    const boxes = document.querySelectorAll('[data-pm-toggle^="list:exclude:"]').length;
    document.querySelector('[data-pm-toggle="list:exclude:0"]').click(); await sleep(800);
    document.querySelector('[data-pm="ok"]').click(); await sleep(600);
    const body = m.actions.buildPart(twin).body;
    const vol = (await import('/src/cad/kernel.js')).rep().measureVolume(body);
    return `${boxes} ${Math.round(vol)}`;
  })()

(async () => {
    const m = window.__mymechanics; const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
    const F = await import('/src/cad/features.js'); const S = await import('/src/cad/sketch.js'); const Rf = await import('/src/cad/refs.js');
    const top = { kind: 'std', name: 'top' };
    await m.run('newPart'); const plate = m.active(); plate.name = 'Plate';
    const ps = F.createFeature(plate, 'sketch', { plane: top, ...S.createSketchGeometry() }); S.addRectangle(ps, -30, -20, 30, 20); S.addCircle(ps, 10, 5, 2);
    m.actions.change('op.addFeature', () => { plate.features.push(ps, F.createFeature(plate, 'extrude', { sketch: ps.id, depth: 5 })); });
    const pb = m.actions.buildPart(plate).body;
    const hole = pb.faces.find((f) => /CYL/.test(f.geomType)); const pTop = pb.faces.find((f) => f.geomType === 'PLANE' && Math.abs(f.center.z - 5) < 1e-6);
    m.actions.change('op.addFeature', () => { plate.features.push(F.createFeature(plate, 'mateReference', { refName: 'Pin', primary: Rf.faceSignature(hole), secondary: Rf.faceSignature(pTop) })); });
    await m.run('newPart'); const pin = m.active(); pin.name = 'Pin';
    const cs = F.createFeature(pin, 'sketch', { plane: top, ...S.createSketchGeometry() }); S.addCircle(cs, 0, 0, 2);
    m.actions.change('op.addFeature', () => { pin.features.push(cs, F.createFeature(pin, 'extrude', { sketch: cs.id, depth: 12 })); });
    const qb = m.actions.buildPart(pin).body;
    const shaft = qb.faces.find((f) => /CYL/.test(f.geomType)); const under = qb.faces.find((f) => f.geomType === 'PLANE' && Math.abs(f.center.z) < 1e-6);
    m.actions.change('op.addFeature', () => { pin.features.push(F.createFeature(pin, 'mateReference', { refName: 'Pin', primary: Rf.faceSignature(shaft), secondary: Rf.faceSignature(under) })); });
    m.actions.cancelEditing?.({ quiet: true });
    m.project.assemblies.push({ id: 'asmMR', name: 'MR', components: [], mates: [] });
    await m.actions.switchDocument({ kind: 'assembly', id: 'asmMR' });
    m.actions.cancelEditing?.({ quiet: true });
    m.actions.insertComponent(plate.id); m.actions.insertComponent(pin.id);
    await sleep(600);
    const a = m.active(); const c = a.components.find((x) => x.part === pin.id);
    return `${a.mates.length} ${a.mates.map((x) => x.type).sort().join(',')} ${c.position.map((v) => v.toFixed(2)).join(',')}`;
  })()
